before:
Complete local Rust example; the app itself does not execute it:
```rust
use std::rc::Rc;

fn main() {
    let first = Rc::new(String::from("read"));
    let second = Rc::clone(&first);
    println!("{}", Rc::strong_count(&first));
    drop(second);
    println!("{}", Rc::strong_count(&first));
}
```

